<?php header("Access-Control-Allow-Origin: *"); header("Content-Type: application/json; charset=UTF-8"); header("Access-Control-Allow-Methods: POST"); header("Access-Control-Allow-Headers: Content-Type, Access-Control-Allow-Methods, Authorization, X-Requested-With"); $host = "localhost"; $user = "root"; $pass = ""; $dbname = "codepixel_studio"; $conn = new mysqli($host, $user, $pass, $dbname); if ($conn->connect_error) { echo json_encode(["success" => false, "message" => "Database connection failed"]); exit(); } if ($_SERVER["REQUEST_METHOD"] === "OPTIONS") { exit(); } $action = isset($_GET["action"]) ? $_GET["action"] : "contact"; if ($action === "review") { $name = isset($_POST["name"]) ? $conn->real_escape_string($_POST["name"]) : ""; $country = isset($_POST["country"]) ? $conn->real_escape_string($_POST["country"]) : ""; $service = isset($_POST["service"]) ? $conn->real_escape_string($_POST["service"]) : ""; $rating = isset($_POST["rating"]) ? intval($_POST["rating"]) : 0; $review = isset($_POST["review"]) ? $conn->real_escape_string($_POST["review"]) : ""; $permission = isset($_POST["permission"]) ? 1 : 0; if (empty($name) || empty($service) || empty($review) || $rating == 0) { echo json_encode(["success" => false, "message" => "Please fill in all required fields"]); exit(); } $sql = "INSERT INTO reviews (name, country, service, rating, review, permission, created_at) VALUES (?, ?, ?, ?, ?, ?, NOW())"; $stmt = $conn->prepare($sql); $stmt->bind_param("sssisi", $name, $country, $service, $rating, $review, $permission); if ($stmt->execute()) { echo json_encode(["success" => true, "message" => "Thank you for your review!"]); } else { echo json_encode(["success" => false, "message" => "Error submitting review"]); } $stmt->close(); } else { $name = isset($_POST["name"]) ? $conn->real_escape_string($_POST["name"]) : ""; $email = isset($_POST["email"]) ? $conn->real_escape_string($_POST["email"]) : ""; $service = isset($_POST["service"]) ? $conn->real_escape_string($_POST["service"]) : ""; $budget = isset($_POST["budget"]) ? $conn->real_escape_string($_POST["budget"]) : ""; $project = isset($_POST["project"]) ? $conn->real_escape_string($_POST["project"]) : ""; if (empty($name) || empty($email) || empty($service) || empty($project)) { echo json_encode(["success" => false, "message" => "Please fill in all required fields"]); exit(); } $sql = "INSERT INTO messages (name, email, service, budget, project, created_at) VALUES (?, ?, ?, ?, ?, NOW())"; $stmt = $conn->prepare($sql); $stmt->bind_param("sss ss", $name, $email, $service, $budget, $project); if ($stmt->execute()) { echo json_encode(["success" => true, "message" => "Thank you! Your message has been sent."]); } else { echo json_encode(["success" => false, "message" => "Error sending message"]); } $stmt->close(); } $conn->close(); ?>
